# Fresh original scan/sequence-statistics/chromVAR execution; no runtime modifications.
args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==2L)
.libPaths(c(normalizePath(args[[2]]),normalizePath('build/literature-review/signac-runtime/reference-setup-1/R-lib'),normalizePath('build/omics-sctransform-r'),.Library),include.site=FALSE)
stopifnot(as.character(packageVersion('motifmatchr'))=='1.34.0',as.character(packageVersion('chromVAR'))=='1.34.1')
BiocParallel::register(BiocParallel::SerialParam())
out<-args[[1]];stopifnot(!dir.exists(out));dir.create(out);warnings<-character();results<-list();capture<-function(f){w<-character();v<-tryCatch(withCallingHandlers(f(),warning=function(x){w<<-c(w,conditionMessage(x));invokeRestart('muffleWarning')}),error=function(e)list(error=conditionMessage(e)));list(value=v,warnings=w)}
set.seed(23017);bases<-c('A','C','G','T');seq1<-paste0(sample(bases,24000,replace=TRUE),collapse='');seq2<-paste0(sample(c(bases,'N'),18000,replace=TRUE,prob=c(0.25,0.2,0.2,0.25,0.1)),collapse='');fasta<-file.path(out,'reference.fa');writeLines(c('>chr1',seq1,'>chr2',seq2),fasta,useBytes=TRUE);Rsamtools::indexFa(fasta);genome<-Rsamtools::FaFile(fasta)
regions<-GenomicRanges::GRanges(rep(c('chr1','chr2'),each=40),IRanges::IRanges(rep(seq(100,by=210,length.out=40),2),width=150));names(regions)<-paste0(as.character(GenomeInfoDb::seqnames(regions)),'-',GenomicRanges::start(regions),'-',GenomicRanges::end(regions))
pfm<-TFBSTools::PFMatrixList(TFBSTools::PFMatrix(ID='M1',name='ACGT',strand='+',bg=setNames(rep(0.25,4),bases),profileMatrix=matrix(c(40,1,1,1,1,40,1,1,1,1,40,1,1,1,1,40),4,dimnames=list(bases,NULL))),TFBSTools::PFMatrix(ID='M2',name='CGCG',strand='+',bg=setNames(rep(0.25,4),bases),profileMatrix=matrix(c(1,40,1,1,1,1,40,1,1,40,1,1,1,1,40,1),4,dimnames=list(bases,NULL))));names(pfm)<-c('M1','M2')
results$region_stats<-capture(function(){x<-Signac::RegionStats(regions,genome=genome,verbose=FALSE);write.table(x,file.path(out,'region-stats.tsv'),sep='\t',quote=FALSE,col.names=NA);list(rows=nrow(x),columns=colnames(x),gc=range(x$GC.percent))})
results$scan<-capture(function(){x<-Signac::CreateMotifMatrix(regions,pwm=pfm,genome=genome);Matrix::writeMM(x,file.path(out,'motif-presence.mtx'));list(dimensions=dim(x),stored=length(x@i),motif_totals=Matrix::colSums(x))})
results$add_motifs<-capture(function(){x<-Signac::AddMotifs(regions,genome=genome,pfm=pfm,verbose=FALSE);saveRDS(x,file.path(out,'motif.rds'));list(dimensions=dim(Signac::GetMotifData(x,slot='data')),positions=vapply(Signac::GetMotifData(x,slot='positions'),length,integer(1)))})
results$chromvar<-capture(function(){
 counts<-matrix(rpois(80*12,lambda=3),80,12,dimnames=list(names(regions),paste0('cell',1:12)));counts[1,]<-0;Matrix::writeMM(as(counts,'dgCMatrix'),file.path(out,'counts.mtx'));assay<-Signac::CreateChromatinAssay(counts=counts,ranges=regions,min.cells=0,min.features=0,motifs=readRDS(file.path(out,'motif.rds')))
 source<-new.env(parent=asNamespace('Signac'));sys.source('src/main/resources/org/jlinalg/omics/signac_motif_legacy_access.R',source);source$GetAssayData<-source$signac_motif_legacy_get_assay_data;sys.source('src/main/resources/org/jlinalg/omics/signac-motifs/1.9.0/RunChromVAR.ChromatinAssay.R',source)
 set.seed(8623);fit<-source$RunChromVAR.ChromatinAssay(assay,genome=genome,niterations=10,bs=8,verbose=FALSE);saveRDS(fit,file.path(out,'chromvar.rds'));x<-SeuratObject::GetAssayData(fit,layer='data');write.table(x,file.path(out,'chromvar-z.tsv'),sep='\t',quote=FALSE,col.names=NA);list(dimensions=dim(x),finite=all(is.finite(x)),range=range(x),historical_wrapper='literal-Signac1.9.0-with-strict-GetAssayData-bridge',chromVAR='1.34.1-current-not-paper-version')
})
writeLines(capture.output(sessionInfo()),file.path(out,'session-info.txt'));jsonlite::write_json(list(status='original-motif-runtime-probe-not-user-analysis-admission',parallel_backend='SerialParam',results=results),file.path(out,'RESULT.json'),pretty=TRUE,auto_unbox=TRUE,digits=17,na='string');cat('ORIGINAL_MOTIF_RUNTIME_PROBE_COMPLETE\n')
